import React, { useState } from 'react';
import axios from 'axios';

const GateSimulator = () => {
    const [qrInput, setQrInput] = useState('QR_SECRET_HASH_12345');
    const [gateStatus, setGateStatus] = useState('LOCKED');
    const [message, setMessage] = useState('Waiting for ticket scan...');

    const handleSimulateScan = async (e) => {
        e.preventDefault();
        try {
            const response = await axios.post('/api/v1/tickets/validate', {
                qrHash: qrInput
            });

            if (response.data.success) {
                setGateStatus('GRANTED');
                setMessage(`✅ ${response.data.message} - Turnstile Unlocked for 3s`);
                
                setTimeout(() => {
                    setGateStatus('LOCKED');
                    setMessage('Waiting for ticket scan...');
                }, 3000);
            }
        } catch (error) {
            setGateStatus('DENIED');
            const errorMsg = error.response?.data?.message || 'Invalid Ticket';
            setMessage(`❌ Access Denied: ${errorMsg}`);
        }
    };

    const getBannerColor = () => {
        if (gateStatus === 'GRANTED') return '#d4edda';
        if (gateStatus === 'DENIED') return '#f8d7da';
        return '#e2e3e5';
    };

    return (
        <div style={{ marginTop: '40px', padding: '20px', border: '2px dashed #666', borderRadius: '8px', maxWidth: '450px' }}>
            <h2>Virtual IoT Turnstile Simulator</h2>
            <p>Enter a QR Hash to simulate scanning a ticket at the physical gate:</p>
            
            <form onSubmit={handleSimulateScan} style={{ display: 'flex', gap: '10px', marginBottom: '15px' }}>
                <input
                    type="text"
                    value={qrInput}
                    onChange={(e) => setQrInput(e.target.value)}
                    placeholder="Enter QR Hash..."
                    style={{ flex: 1, padding: '8px' }}
                />
                <button type="submit" style={{ padding: '8px 16px', cursor: 'pointer' }}>
                    Scan QR
                </button>
            </form>

            <div style={{ padding: '15px', backgroundColor: getBannerColor(), borderRadius: '5px', fontWeight: 'bold' }}>
                Gate State: {gateStatus} <br />
                <span style={{ fontWeight: 'normal', fontSize: '0.9em' }}>{message}</span>
            </div>
        </div>
    );
};

export default GateSimulator;
